const AUTHORITY_SQL = `
CREATE TABLE role_authority_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version TEXT NOT NULL,issuer TEXT NOT NULL,issuer_key_id TEXT NOT NULL,authority_key_fingerprint TEXT NOT NULL,trust_domain TEXT NOT NULL,audience TEXT NOT NULL,origin TEXT NOT NULL,enrollment_namespace TEXT NOT NULL,build_policy_sha256 TEXT NOT NULL,accepted_snapshot_id TEXT NOT NULL,accepted_snapshot_sha256 TEXT NOT NULL,policy_json TEXT NOT NULL CHECK(json_valid(policy_json))) STRICT;
CREATE TABLE launch_key_assignments(assignment_id TEXT PRIMARY KEY,assignment_sha256 TEXT NOT NULL UNIQUE,role TEXT NOT NULL,scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),subject_json TEXT NOT NULL CHECK(json_valid(subject_json)),launch_json TEXT NOT NULL CHECK(json_valid(launch_json)),descriptor_json TEXT NOT NULL CHECK(json_valid(descriptor_json)),public_key_pem TEXT NOT NULL,key_fingerprint TEXT NOT NULL UNIQUE,writer_credential_json TEXT CHECK(writer_credential_json IS NULL OR json_valid(writer_credential_json)),issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_session TEXT UNIQUE,state TEXT NOT NULL CHECK(state IN('OPEN','CONSUMED','REVOKED')),envelope_json TEXT NOT NULL CHECK(json_valid(envelope_json))) STRICT;
CREATE TABLE role_sessions(session_id TEXT PRIMARY KEY,assignment_id TEXT NOT NULL UNIQUE REFERENCES launch_key_assignments(assignment_id),role TEXT NOT NULL,scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),subject_json TEXT NOT NULL CHECK(json_valid(subject_json)),launch_json TEXT NOT NULL CHECK(json_valid(launch_json)),descriptor_json TEXT NOT NULL CHECK(json_valid(descriptor_json)),public_key_pem TEXT NOT NULL,key_fingerprint TEXT NOT NULL UNIQUE,writer_credential_json TEXT CHECK(writer_credential_json IS NULL OR json_valid(writer_credential_json)),issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked INTEGER NOT NULL CHECK(revoked IN(0,1)),status_version INTEGER NOT NULL,enrollment_json TEXT NOT NULL CHECK(json_valid(enrollment_json))) STRICT;
CREATE TABLE role_challenges(nonce_id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('REGISTRATION','ACTION')),owner_id TEXT NOT NULL,request_id TEXT NOT NULL,intent_sha256 TEXT NOT NULL,nonce TEXT NOT NULL,action TEXT,purpose_class TEXT,reserved_action_id TEXT,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_request TEXT,envelope_json TEXT NOT NULL CHECK(json_valid(envelope_json)),UNIQUE(kind,owner_id,request_id)) STRICT;
CREATE TABLE role_action_requests(session_id TEXT NOT NULL REFERENCES role_sessions(session_id),request_id TEXT NOT NULL,intent_sha256 TEXT NOT NULL,body_sha256 TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),action TEXT NOT NULL,purpose_class TEXT NOT NULL,logical_action_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('COMMITTED','CONFLICT')),receipt_json TEXT NOT NULL CHECK(json_valid(receipt_json)),observed_at TEXT NOT NULL,PRIMARY KEY(session_id,request_id),UNIQUE(logical_action_id,action)) STRICT;
CREATE TABLE role_domain_associations(kind TEXT NOT NULL,logical_id TEXT NOT NULL,payload_sha256 TEXT NOT NULL,session_id TEXT NOT NULL,related_id TEXT,created_at TEXT NOT NULL,PRIMARY KEY(kind,logical_id)) STRICT;
CREATE TRIGGER assignments_no_update BEFORE UPDATE ON launch_key_assignments WHEN OLD.state='REVOKED' OR OLD.state='CONSUMED' AND NEW.state!='CONSUMED' BEGIN SELECT RAISE(ABORT,'assignment state is monotonic'); END;
CREATE TRIGGER action_requests_no_update BEFORE UPDATE ON role_action_requests BEGIN SELECT RAISE(ABORT,'action requests are immutable'); END;
CREATE TRIGGER action_requests_no_delete BEFORE DELETE ON role_action_requests BEGIN SELECT RAISE(ABORT,'action requests are immutable'); END;
`;

function hash(value: string | Buffer): string { return createHash("sha256").update(value).digest("hex"); }
