function validateScope(scope: RoleRunScope): void { exact(scope as unknown as Record<string, unknown>, ["account_id", "deployment_id", "environment_instance_id", "environment_type", "organization_id", "run_id", "spec_sha256", "tenant_id"]); if (![scope.environment_type, scope.environment_instance_id, scope.deployment_id, scope.organization_id, scope.tenant_id, scope.account_id, scope.run_id].every((v) => TOKEN.test(v)) || !SHA256.test(scope.spec_sha256)) throw new CatfoodTrustError("ROLE_CHANNEL_SCOPE_INVALID"); }
function validateBinding(binding: RoleChannelBinding): void { validatePolicy(binding.policy); if (![binding.issuer, binding.issuer_key_id, binding.audience, binding.origin, binding.credential, binding.enrollment_namespace, binding.accepted_snapshot_id].every((v) => typeof v === "string" && v.length > 0) || binding.credential.length < 32 || !SHA256.test(binding.build_policy_sha256) || !SHA256.test(binding.accepted_snapshot_sha256)) throw new CatfoodTrustError("ROLE_CHANNEL_BINDING_INVALID"); const url = new URL(binding.origin); const loopback = ["localhost", "127.0.0.1", "::1", "[::1]"].includes(url.hostname.toLowerCase()); if (url.username || url.password || url.search || url.hash || !["", "/"].includes(url.pathname) || (binding.trust_domain === "TEST_ONLY" ? !loopback || !["http:", "https:"].includes(url.protocol) : url.protocol !== "https:")) throw new CatfoodTrustError("ROLE_CHANNEL_BINDING_INVALID"); const key = createPublicKey(binding.authority_public_key_pem); if (key.asymmetricKeyType !== "ed25519") throw new CatfoodTrustError("ROLE_CHANNEL_BINDING_INVALID"); }
